// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testFuzz_property(address actor, address key) public {
        // owner is the deployer (this test contract); pick any other caller
        vm.assume(actor != address(this));
        vm.assume(actor != address(0));

        bool ok;
        vm.prank(actor);
        try c.NETM() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a non-owner can never successfully run NETM, so no
        // state changes happen: the call reverts and balances stay zero
        // at every key, including the caller's own (owner) key.
        assertTrue(
            !ok &&
            c.balanceOf(actor) == 0 &&
            c.balanceOf(key) == 0
        );
    }
}
